package leetcode.medium;

import org.junit.Assert;
import org.junit.Test;

public class OnlineStockSpanTest {

 @Test
 public void nextPriceIsGreaterThanPreviousPriceTest() {
   OnlineStockSpan onlineStockSpan = new OnlineStockSpan();

   int actual = onlineStockSpan.next(3);
   Assert.assertEquals(1, actual);

   actual = onlineStockSpan.next(5);
   Assert.assertEquals(2, actual);

   actual = onlineStockSpan.next(1);
   Assert.assertEquals(1, actual);

   actual = onlineStockSpan.next(4);
   Assert.assertEquals(2, actual);
 }

 @Test
 public void nextPriceIsLessThanPreviousPriceTest() {
   OnlineStockSpan onlineStockSpan = new OnlineStockSpan();

   int actual = onlineStockSpan.next(6);
   Assert.assertEquals(1, actual);

   actual = onlineStockSpan.next(5);
   Assert.assertEquals(1, actual);

   actual = onlineStockSpan.next(3);
   Assert.assertEquals(1, actual);

   actual = onlineStockSpan.next(2);
   Assert.assertEquals(1, actual);
 }

 @Test
 public void nextPriceIsEqualToPreviousPriceTest() {
   OnlineStockSpan onlineStockSpan = new OnlineStockSpan();

   int actual = onlineStockSpan.next(7);
   Assert.assertEquals(1, actual);

   actual = onlineStockSpan.next(7);
   Assert.assertEquals(2, actual);

   actual = onlineStockSpan.next(7);
   Assert.assertEquals(3, actual);
 }

 @Test
 public void calculateSpansAllPricesAreEqualTest() {
   OnlineStockSpan onlineStockSpan = new OnlineStockSpan();

   int[] prices = {4, 4, 4, 4};
   int[] actual = onlineStockSpan.calculateSpans(prices);
   int[] expected = {1, 2, 3, 4};
   Assert.assertArrayEquals(expected, actual);
 }

 @Test
 public void calculateSpansPricesAreInIncreasingOrderTest() {
   OnlineStockSpan onlineStockSpan = new OnlineStockSpan();

   int[] prices = {1, 2, 3, 4, 5};
   int[] actual = onlineStockSpan.calculateSpans(prices);
   int[] expected = {1, 2, 3, 4, 5};
   Assert.assertArrayEquals(expected, actual);
 }

 @Test
 public void calculateSpansPricesAreInDecreasingOrderTest() {
   OnlineStockSpan onlineStockSpan = new OnlineStockSpan();

   int[] prices = {5, 4, 3, 2, 1};
   int[] actual = onlineStockSpan.calculateSpans(prices);
   int[] expected = {1, 1, 1, 1, 1};
   Assert.assertArrayEquals(expected, actual);
 }
}
